package com.owindev.gcs.feature.map

import java.io.File
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.amshove.kluent.shouldBeEmpty
import org.amshove.kluent.shouldBeEqualTo
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Tag
import org.junit.jupiter.api.Test

/** The night style as shipped in the assets, generated by `tools/map/make_night_style.py` from liberty. */
@Tag("REQ-034")
class NightStyleTest {

    private lateinit var style: JsonObject

    @BeforeEach
    fun setUp() {
        style = Json.parseToJsonElement(File(ASSETS, NIGHT_STYLE_ASSET).readText()).jsonObject
    }

    @Test
    fun `GIVEN the night style WHEN reading where it loads from THEN is only OpenFreeMap over HTTPS`() {
        val sources = style.getValue("sources").jsonObject

        val result = listOf(
            sources.getValue("openmaptiles").jsonObject.getValue("url").jsonPrimitive.content,
            style.getValue("sprite").jsonPrimitive.content,
            style.getValue("glyphs").jsonPrimitive.content,
        ) + sources.getValue("ne2_shaded").jsonObject.getValue("tiles").jsonArray.map { it.jsonPrimitive.content }

        result.filterNot { it.startsWith(OPENFREEMAP) }.shouldBeEmpty()
    }

    @Test
    fun `GIVEN the night style WHEN counting its layers THEN keeps every layer of liberty`() {
        val layers = style.getValue("layers").jsonArray

        val result = layers.size

        result shouldBeEqualTo LIBERTY_LAYERS
    }

    @Test
    fun `GIVEN the night style WHEN reading its labels THEN every text has a halo to read over the roads`() {
        val labels = style.getValue("layers").jsonArray.map { it.jsonObject }
            .filter { it.getValue("type").jsonPrimitive.content == "symbol" }
            .map { it.getValue("id").jsonPrimitive.content to it["paint"]?.jsonObject.orEmpty() }

        val result = labels.filter { (_, paint) -> "text-color" in paint && "text-halo-color" !in paint }

        result.shouldBeEmpty()
    }
}

/** The module's assets, as the unit tests see them from the module's directory. */
private val ASSETS = File("src/main/assets")

private const val OPENFREEMAP = "https://tiles.openfreemap.org/"

/** Liberty's layers on 2026-10-21 (https://tiles.openfreemap.org/styles/liberty), shields and POI icons included. */
private const val LIBERTY_LAYERS = 111
